import { renderApp as renderAppSpec } from "../../reads/render.js";
import { serializeFormer } from "../../reads/former-lowering.js";
import { serializeView } from "../../reads/view-lowering.js";
import { readBackApp } from "../../reads/read-back.js";
import { inventoryOf } from "../concepts/introspect.js";
export function exportReactions(state) {
    return {
        reactions: [...state.loweredReactions].flat(),
        views: [...state.registry.viewRefs()].map((ref) => serializeView(ref, state.registry.authoredIdentityOf(ref))),
        formers: [...state.registry.formerRefs()].map((ref) => serializeFormer(ref, state.registry.authoredIdentityOf(ref))),
        unlowered: [...state.unloweredReactions],
    };
}
export function exportConcepts(state) {
    const inventories = [];
    for (const instrumented of state.registry.concepts.values()) {
        const raw = state.rawConceptOf(instrumented);
        inventories.push(inventoryOf(raw));
    }
    return inventories;
}
export function readBack(state) {
    const app = state.exportReactions();
    return readBackApp(app.views, app.formers, app.reactions, app.unlowered, state.registry.readBackEnv());
}
export function renderApp(state, title = "Application") {
    return renderAppSpec({
        title,
        concepts: exportConcepts(state),
        app: state.exportReactions(),
    });
}
